<template>
 <ElSpace direction="vertical" fill class="v1-page" :size="20">
  <ElPageHeader :title="'设备中心'" :content="mode==='meters'?'智能电表':'设施与回路'" @back="$emit('navigate','overview')"><template #extra><ElSpace><ElButton v-if="mode!=='meters'" type="warning" plain @click="stopAutomation">暂停自动化</ElButton><ElButton type="primary" :disabled="!admin" @click="edit()">新增{{mode==='meters'?'电表':'设施'}}</ElButton></ElSpace></template></ElPageHeader>
  <ElCard shadow="never"><ElSpace wrap><ElInput v-model="search" placeholder="设备名称" clearable style="width:250px"><template #prefix><ArtSvgIcon icon="ri:search-line" /></template></ElInput><ElSelect v-model="area" placeholder="全部区域" clearable style="width:180px"><ElOption v-for="a in areas" :key="a" :label="a" :value="a" /></ElSelect><ElTag>{{filtered.length}} 台</ElTag></ElSpace></ElCard>
  <ElEmpty v-if="!filtered.length" description="暂无设备" />
  <ElRow :gutter="20"><ElCol v-for="d in filtered" :key="d.id" :xs="24" :md="12" :xl="8" class="v1-card-col"><ElCard shadow="hover" :class="['v1-device-card',{'is-critical':over(d)}]"><template #header><ElSpace class="v1-spread"><ElSpace><ArtSvgIcon :icon="icon(d)" class="v1-device-icon" /><strong>{{d.name}}</strong></ElSpace><ElTag :type="d.communication==='online'?'success':d.communication==='unknown'?'info':'warning'">{{state(d.communication)}}</ElTag></ElSpace></template>
   <ElSpace class="v1-device-meta"><ElTag effect="plain">{{d.area}}</ElTag><ElTag :type="d.source==='simulated'?'warning':'info'">{{d.source==='simulated'?'演示':d.source==='gateway'?'网关':'API'}}</ElTag><ElTooltip v-if="d.api?.failures" :content="d.api.status"><ElTag type="danger">{{d.api.failures}} 次失败</ElTag></ElTooltip><ElTag>{{d.quality==='demo'?'演示':d.quality==='expired'?'过期':d.quality==='missing'?'暂无数据':'实测'}}</ElTag><ElTooltip :content="date(d.updated_at)"><ElButton text circle aria-label="更新时间"><ArtSvgIcon icon="ri:time-line" /></ElButton></ElTooltip></ElSpace>
   <div class="v1-device-identity"><ElDescriptions v-if="d.source==='gateway'" :column="1" size="small"><ElDescriptionsItem label="设备 ID"><ElSpace><ElText truncated class="v1-device-id">{{d.id}}</ElText><ElButton link type="primary" @click="copy(d.id,'设备 ID')">复制</ElButton></ElSpace></ElDescriptionsItem></ElDescriptions></div>
   <div class="v1-device-stat"><ElStatistic :title="d.capabilities.balance?'剩余电量':d.capabilities.power?'当前功率':'设备类型'" :value="d.capabilities.balance ? (d.api?.reading?.balance ?? '暂无数据') : d.capabilities.power ? (d.online&&d.has_power?n(d.power_w/1000,2):'暂无数据') : typeName(d.device_type)" :value-style="{color:over(d)?'var(--el-color-danger)':'var(--el-text-color-primary)'}"><template #suffix><span v-if="d.capabilities.balance">kWh</span><span v-else-if="d.capabilities.power">kW</span></template></ElStatistic></div>
   <div class="v1-device-alert"><ElAlert v-if="over(d)" title="功率超限" type="error" :closable="false" show-icon /></div>
   <div class="v1-device-details"><ElDescriptions v-if="mode!=='meters'" :column="2"><ElDescriptionsItem v-if="d.capabilities.switch" label="开关"><ElTag :type="d.switch_state==='closed'?'success':'info'">{{d.switch_state==='closed'?'合':d.switch_state==='open'?'分':'未知'}}</ElTag></ElDescriptionsItem><ElDescriptionsItem label="控制范围">{{related(d).length}} 台</ElDescriptionsItem></ElDescriptions></div>
   <div class="v1-device-command"><ElTooltip v-if="mode!=='meters'&&d.last_command" :content="d.last_command.detail"><ElTag :type="d.execution==='success'?'success':d.execution==='failed'?'danger':'warning'">{{({running:'执行中',success:'执行成功',failed:'执行失败',unknown:'结果未知'})[d.execution]}}</ElTag></ElTooltip></div>
   <ElSpace class="v1-device-actions"><ElButton v-if="mode!=='meters'&&d.capabilities.switch" :type="d.relay_on?'danger':'primary'" plain :disabled="!d.online||d.execution==='running'||(d.protected&&d.relay_on)||user.role==='viewer'" @click="$emit('control',d)">{{d.relay_on?'断开':'接通'}}</ElButton><ElTag v-if="d.protected" type="danger">保护设备</ElTag><ElButton v-if="d.source==='third_party'" :loading="querying===d.id" :disabled="user.role!=='admin'" @click="query(d)">查询</ElButton><ElButton v-if="d.source==='third_party'" @click="history(d)">读数</ElButton><ElButton :disabled="!admin" @click="edit(d)">编辑</ElButton><ElTooltip v-if="mode!=='meters'&&d.capabilities.switch" :content="planReason(d)" :disabled="canPlan(d)"><span><ElButton :disabled="!canPlan(d)" @click="plan(d)">计划</ElButton></span></ElTooltip><ElDropdown v-if="admin" @command="()=>retire(d)"><ElButton circle aria-label="更多操作"><ArtSvgIcon icon="ri:more-line" /></ElButton><template #dropdown><ElDropdownMenu><ElDropdownItem command="retire">退役</ElDropdownItem></ElDropdownMenu></template></ElDropdown></ElSpace>
  </ElCard></ElCol></ElRow>
  <ElCard v-if="mode!=='meters'" shadow="never"><template #header>自动计划</template><ArtTable :data="schedules" :show-table-header="false" height="260" empty-height="200px"><ElTableColumn prop="device_name" label="设施" /><ElTableColumn prop="at" label="执行时间" /><ElTableColumn label="动作"><template #default="{row}">{{row.desired?'接通':'断开'}}</template></ElTableColumn><ElTableColumn label="状态"><template #default="{row}"><ElSwitch :model-value="!!row.enabled" :disabled="!admin" @change="enabled=>toggle(row,enabled)" /></template></ElTableColumn><ElTableColumn prop="last_result" label="结果" /></ArtTable></ElCard>
 </ElSpace>
 <ElDrawer v-model="open" :title="draft.id?'编辑设备':mode==='meters'?'新增智能电表':'新增设施与回路'" direction="rtl" size="min(580px, 100vw)" :close-on-click-modal="false" destroy-on-close>
  <ArtForm ref="deviceForm" v-model="draft" :items="fields" :span="12" label-position="top" :show-reset="false" :show-submit="false" :rules="validation" />
  <ApiDeviceFields v-if="draft.source==='third_party'" v-model="apiDraft" :rooms="rooms" />
  <ElAlert v-if="error" :title="error" type="error" show-icon :closable="false" />
  <template #footer><ElButton @click="open=false">取消</ElButton><ElButton type="primary" :loading="busy" @click="save">保存</ElButton></template>
 </ElDrawer>
 <ElDrawer v-model="planOpen" title="自动计划" direction="rtl" size="min(480px, 100vw)"><ArtForm v-model="schedule" :items="planFields" :span="24" label-position="top" :show-reset="false" :show-submit="false" /><ElTag>北京时间</ElTag><ElAlert v-if="error" :title="error" type="error" :closable="false" /><template #footer><ElButton @click="planOpen=false">取消</ElButton><ElButton type="primary" :loading="busy" @click="savePlan">保存计划</ElButton></template></ElDrawer>
 <ElDialog v-model="historyOpen" title="读数与预测" width="min(960px, 94vw)" align-center><ElSpace direction="vertical" fill class="v1-page"><ElStatistic title="预计可用" :value="historyData?.forecast?.forecast?.available ? n(historyData.forecast.forecast.remaining_hours,1) : '学习中'"><template #suffix>小时</template></ElStatistic><ArtTable :data="historyData?.readings||[]" :show-table-header="false" height="320"><ElTableColumn label="时间" min-width="180"><template #default="{row}">{{date(row.ts)}}</template></ElTableColumn><ElTableColumn prop="balance" label="余额 / kWh" /><ElTableColumn prop="cumulative" label="累计 / kWh" /><ElTableColumn prop="power" label="功率 / W" /><ElTableColumn prop="quality" label="质量" /></ArtTable><ElDivider>采集记录</ElDivider><ArtTable :data="historyData?.attempts||[]" :show-table-header="false" height="240"><ElTableColumn label="时间" min-width="180"><template #default="{row}">{{date(row.ts)}}</template></ElTableColumn><ElTableColumn label="状态"><template #default="{row}"><ElTag :type="row.state==='failed'?'danger':'success'">{{row.state==='failed'?'失败':row.state==='success'?'成功':'查询中'}}</ElTag></template></ElTableColumn><ElTableColumn prop="message" label="结果" min-width="250" /></ArtTable></ElSpace></ElDialog>
 <ElDialog v-model="connectOpen" title="HTTP 网关设备已生成" width="min(680px, 94vw)" :close-on-click-modal="false" align-center>
  <ElSpace direction="vertical" fill :size="20" class="v1-dialog-stack">
   <ElAlert title="把下面的设备 ID 填入网关或模拟平台的设备映射中" type="success" show-icon :closable="false" />
   <ElDescriptions :column="1" border>
    <ElDescriptionsItem label="设备名称">{{connection.name}}</ElDescriptionsItem>
    <ElDescriptionsItem label="设备 ID"><ElInput class="v1-copy-field" :model-value="connection.id" readonly><template #append><ElButton @click="copy(connection.id,'设备 ID')">复制</ElButton></template></ElInput></ElDescriptionsItem>
    <ElDescriptionsItem label="所属网关"><ElInput class="v1-copy-field" :model-value="connection.gateway_id" readonly><template #append><ElButton @click="copy(connection.gateway_id,'网关 ID')">复制</ElButton></template></ElInput></ElDescriptionsItem>
    <ElDescriptionsItem label="上报地址"><ElInput class="v1-copy-field" :model-value="gatewayBase+'/api/gateway/telemetry'" readonly><template #append><ElButton @click="copy(gatewayBase+'/api/gateway/telemetry','上报地址')">复制</ElButton></template></ElInput></ElDescriptionsItem>
   </ElDescriptions>
  </ElSpace>
  <template #footer><ElButton type="primary" @click="connectOpen=false">完成</ElButton></template>
 </ElDialog>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {api,n,date} from './api';
import ApiDeviceFields from './ApiDeviceFields.vue';
import {apiDefaults,apiConfig} from './api-device';
const props=defineProps({mode:String,spaceId:String,devices:Array,user:Object,gateways:Array});const emit=defineEmits(['refresh','control','navigate']);
const search=ref(''),area=ref(''),open=ref(false),busy=ref(false),error=ref(''),draft=ref({}),apiDraft=ref(apiDefaults()),rooms=ref([]),deviceForm=ref(),querying=ref(''),schedules=ref([]),planOpen=ref(false),schedule=ref({}),historyOpen=ref(false),historyData=ref(null),connectOpen=ref(false),connection=ref({});
const gatewayBase=window.location.origin;
const admin=computed(()=>['admin','demo'].includes(props.user.role));const types=[{value:'readonly_meter',label:'只读电表'},{value:'control_meter',label:'带控制电表'},{value:'socket',label:'智能插座'},{value:'breaker',label:'断路器'},{value:'appliance',label:'普通用电器'}];
const typeName=t=>types.find(x=>x.value===t)?.label||t;const state=s=>({online:'在线',offline:'离线',unknown:'未知'}[s]||'未知');const icon=d=>d.device_type?.includes('meter')?'ri:dashboard-3-line':d.device_type==='breaker'?'ri:git-branch-line':'ri:plug-line';const related=d=>props.devices.filter(x=>x.controller_id===d.id||x.meter_parent_id===d.id);const over=d=>d.online&&d.has_power&&d.power_w!=null&&d.power_w>=d.threshold_w;
const canPlan=d=>admin.value&&!d.protected&&['simulated','gateway'].includes(d.source)&&d.capabilities.switch;const planReason=d=>!admin.value?'需要管理员权限':d.protected?'保护设备不能创建自动计划':d.source==='third_party'?'第三方只读设备不能创建开关计划':'该设备没有可用的计划控制能力';
const listed=computed(()=>props.devices.filter(d=>props.mode==='meters'?d.device_type?.includes('meter'):!d.device_type?.includes('meter')||d.device_type==='control_meter'));const areas=computed(()=>[...new Set(listed.value.map(x=>x.area))]);const filtered=computed(()=>listed.value.filter(d=>(!area.value||d.area===area.value)&&(!search.value||(d.name+d.area).includes(search.value))));
const field=(key,label,type='input',props={})=>({key,label,type,props});const options=rows=>rows.map(d=>({label:d.name,value:d.id}));
const fields=computed(()=>{const apiSource=draft.value.source==='third_party',plain=draft.value.device_type==='appliance';return [field('name','名称'),field('area','区域'),field('device_type','类型','select',{disabled:!!draft.value.id,options:types.filter(t=>t.value===draft.value.device_type||(props.mode==='meters'?t.value.includes('meter'):!t.value.includes('meter')))}),field('source','数据源','select',{disabled:!!draft.value.id,options:[{value:'simulated',label:'模拟'},{value:'gateway',label:'HTTP 网关',disabled:props.user.role!=='admin'},{value:'third_party',label:'第三方 API',disabled:props.user.role!=='admin'}]}),...(draft.value.source==='gateway'?[field('gateway_id','网关','select',{options:options(props.gateways||[])})]:[]),field('meter_parent_id','上级计量点','select',{clearable:true,options:options(props.devices.filter(d=>d.id!==draft.value.id&&d.capabilities.energy))}),...(props.mode!=='meters'?[field('controller_id','关联控制器','select',{clearable:true,options:options(props.devices.filter(d=>d.id!==draft.value.id&&d.capabilities.switch))})]:[]),...(!apiSource&&!plain?[field('nominal_w','额定功率 / W','number',{min:1,max:100000000,controlsPosition:'right'}),field('threshold_w','告警功率 / W','number',{min:1,max:100000000,controlsPosition:'right'}),field('phases','相数','select',{options:[{value:1,label:'单相'},{value:3,label:'三相'}]}),field('nominal_voltage','额定电压 / V','number',{min:1,max:1000}),...(draft.value.device_type==='readonly_meter'?[]:[field('protected','保护设备','switch')])]:[]),field('scale','计量倍率','number',{min:.000001,max:1000000,precision:6}),...(draft.value.id?[field('effective_at','统计生效时间','datetime',{type:'datetime',valueFormat:'X',disabledDate:date=>date.getTime()<Date.now()-86400000})]:[])]});
const validation={name:[{required:true,message:'请输入名称',trigger:'blur'}],area:[{required:true,message:'请输入区域',trigger:'blur'}]};
const planFields=[field('device_name','设施','input',{disabled:true}),field('at','时间','timepicker',{format:'HH:mm',valueFormat:'HH:mm'}),field('desired','动作','select',{options:[{value:true,label:'接通'},{value:false,label:'断开'}]}),field('weekdays','执行日期','checkboxgroup',{options:['周一','周二','周三','周四','周五','周六','周日'].map((label,value)=>({label,value}))})];
async function edit(d){error.value='';rooms.value=d?.api?.rooms||[];draft.value=d?{...d,effective_at:undefined}:{name:'',area:'',device_type:props.mode==='meters'?'readonly_meter':'socket',source:'simulated',nominal_w:1000,threshold_w:1500,phases:1,nominal_voltage:220,scale:1,protected:false};apiDraft.value=apiDefaults();if(d?.source==='third_party')try{apiDraft.value=apiDefaults((await api('device-api-config?device_id='+d.id)).config)}catch(e){error.value=e.message}open.value=true}
async function save(){try{await deviceForm.value.validate();busy.value=true;error.value='';const saved=await api('devices',{...draft.value,effective_at:draft.value.effective_at?Number(draft.value.effective_at):undefined,space_id:props.spaceId,api_config:draft.value.source==='third_party'?{...apiConfig(apiDraft.value),scale:draft.value.scale}:undefined});open.value=false;emit('refresh');ElMessage.success('已保存');if(saved.source==='gateway'){connection.value=saved;connectOpen.value=true}}catch(e){error.value=e.message||'请检查必填字段'}finally{busy.value=false}}
async function copy(value,label='内容'){try{await navigator.clipboard.writeText(String(value||''));ElMessage.success(label+'已复制')}catch(e){ElMessage.error('复制失败，请手动选择复制')}}
async function query(d){querying.value=d.id;try{await api('device-query',{device_id:d.id});emit('refresh');ElMessage.success('查询完成')}catch(e){ElMessage.error(e.message)}finally{querying.value=''}}
async function load(){try{schedules.value=(await api('schedules?space_id='+props.spaceId)).schedules}catch(e){ElMessage.error(e.message)}}
function plan(d){error.value='';schedule.value={device_id:d.id,device_name:d.name,at:'22:00',desired:false,weekdays:[0,1,2,3,4,5,6]};planOpen.value=true}
async function savePlan(){busy.value=true;try{await api('schedules',schedule.value);planOpen.value=false;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function toggle(row,enabled){try{await api('schedule_toggle',{id:row.id,enabled});await load()}catch(e){ElMessage.error(e.message)}}
async function stopAutomation(){try{await ElMessageBox.confirm('暂停当前空间所有自动计划？','暂停自动化',{type:'warning'});await api('automation-stop',{space_id:props.spaceId});await load()}catch(e){if(e?.message)ElMessage.error(e.message)}}
async function retire(d){try{await ElMessageBox.confirm('退役 '+d.name+'？历史记录保留。','退役设备',{type:'warning'});await api('device-retire',{id:d.id});emit('refresh')}catch(e){if(e?.message)ElMessage.error(e.message)}}
async function history(d){try{historyData.value=await api('device-history?device_id='+d.id);historyOpen.value=true}catch(e){ElMessage.error(e.message)}}
watch(()=>draft.value.phases,v=>{if(!draft.value.id)draft.value.nominal_voltage=v===3?380:220});watch(()=>draft.value.source,v=>{if(v==='third_party')draft.value.device_type='readonly_meter'});watch(()=>props.mode,()=>{area.value='';search.value=''});let timer;onMounted(()=>{load();timer=setInterval(load,15000)});onBeforeUnmount(()=>clearInterval(timer));
</script>
